'use strict';
// librsync signature (BLAKE2 variant), as produced by librsync.net in the SDK.
// Block length and strong-sum length are the library defaults and must be checked
// against a signature generated by the real SDK before relying on this.
const fs = require('fs');
const blake2b = require('blake2b');

const MAGIC = 0x72730137; // RS_BLAKE2_SIG_MAGIC
const BLOCK_LEN = 2048;
const STRONG_LEN = 32;
const CHAR_OFFSET = 31;

function weakSum(buf) {
  let s1 = 0, s2 = 0;
  for (let i = 0; i < buf.length; i++) {
    s1 = (s1 + buf[i] + CHAR_OFFSET) & 0xffff;
    s2 = (s2 + s1) & 0xffff;
  }
  return ((s2 << 16) | s1) >>> 0;
}

async function writeSignature(srcPath, destPath, signal) {
  const src = await fs.promises.open(srcPath, 'r');
  const dest = await fs.promises.open(destPath, 'w');
  try {
    const header = Buffer.alloc(12);
    header.writeUInt32BE(MAGIC, 0);
    header.writeUInt32BE(BLOCK_LEN, 4);
    header.writeUInt32BE(STRONG_LEN, 8);
    await dest.write(header);

    const chunk = Buffer.alloc(BLOCK_LEN * 2048); // 4 MiB, a whole number of blocks
    let pos = 0;
    for (;;) {
      if (signal?.aborted) throw new Error('Cancelled');
      const { bytesRead } = await src.read(chunk, 0, chunk.length, pos);
      if (bytesRead === 0) break;
      pos += bytesRead;
      const out = Buffer.alloc(Math.ceil(bytesRead / BLOCK_LEN) * (4 + STRONG_LEN));
      let o = 0;
      for (let off = 0; off < bytesRead; off += BLOCK_LEN) {
        const block = chunk.subarray(off, Math.min(off + BLOCK_LEN, bytesRead));
        out.writeUInt32BE(weakSum(block), o); o += 4;
        Buffer.from(blake2b(STRONG_LEN).update(block).digest()).copy(out, o); o += STRONG_LEN;
      }
      await dest.write(out, 0, o);
    }
  } finally {
    await src.close(); await dest.close();
  }
}

module.exports = { writeSignature, BLOCK_LEN, STRONG_LEN };
